<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\{Order,OrderItem,Product}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class OrderController extends Controller {
 public function index(Request $r){$u=$r->attributes->get('app_user');return response()->json(['ok'=>true,'orders'=>Order::where('buyer_user_id',$u->id)->latest()->get()]);}
 public function store(Request $r){$d=$r->validate(['product_id'=>'required|integer|exists:products,id','quantity'=>'required|integer|min:1|max:99','delivery_address'=>'required|array','payment_method'=>'required|string|max:50']);$u=$r->attributes->get('app_user');$p=Product::where('id',$d['product_id'])->where('status','active')->firstOrFail();abort_if($p->stock<$d['quantity'],422,'Insufficient stock.');$subtotal=$p->price*$d['quantity'];$rate=(float)config('chatcart.commission_percent');$commission=round($subtotal*$rate/100,2);$order=DB::transaction(function()use($u,$p,$d,$subtotal,$commission){$o=Order::create(['order_no'=>'CC-'.now()->format('Ymd').'-'.strtoupper(Str::random(7)),'buyer_user_id'=>$u->id,'subtotal'=>$subtotal,'commission'=>$commission,'total'=>$subtotal,'currency'=>$p->currency,'payment_method'=>$d['payment_method'],'payment_status'=>'unpaid','status'=>'pending','delivery_address'=>$d['delivery_address']]);OrderItem::create(['order_id'=>$o->id,'product_id'=>$p->id,'seller_user_id'=>$p->seller_user_id,'title'=>$p->title,'quantity'=>$d['quantity'],'unit_price'=>$p->price,'line_total'=>$subtotal]);$p->decrement('stock',$d['quantity']);return $o;});return response()->json(['ok'=>true,'order'=>$order],201);}
}
